def get_total_number_of_sequences(m, n):
    def is_valid(num):
        if num < 1:
            return False
        for i in range(1, n):
            if i == 0:
                prev = None
            else:
                prev = num - 1
            if prev is None:
                return False
            if prev * 2 > num:
                return False
        return True
    sequences = []
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if is_valid(j):
                sequences.append((i, j))
    return len(sequences)

