    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n):
        for j in range(i + 1, n + 1):
            if str[i] == str[j]:
                dp[i][j] = dp[i - 1][j - 1] + 1
    return max(dp)

