def rearrange_bigger(n):
    def get_digits(s):
        return [int(d) for d in s]
    n_str = str(n)
    digits = get_digits(n_str)
    max_digit = max(digits)
    for i in range(len(digits)):
        if digits[i] < max_digit:
            digits[i], digits[-i - 1] = digits[-i - 1], digits[i]
    n_str = "".join(digits)
    return int(n_str)

